head.script:
scwin.objParam = new Object();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(panel_Item);
        $c.bns.BnsPanelToGroupBox(pnl_Input);

        // 호출파라미터설정
        scwin.setParam();
        // 면제사유코드
        scwin.setComboCode();

        // 상장수수료 면제사유 비활성화
        cmb_BndListFeeExmptRsnCd.setDisabled(true);

        // 변경상장 수수료등록 조회
        const dsNm = 'BNS_CHG_ANULFEE_INSERT_INFO';
        let qryId;
        let param;
        /** 201, 205, 202 */
        if (scwin.objParam.MKTACT_TP_CD === '201' || scwin.objParam.MKTACT_TP_CD === '205' || scwin.objParam.MKTACT_TP_CD === '202') {
            qryId = 'lds.stf.bnschg.select.selectChgBndListFee';
            param += '&{P}V_MKTACT_TP_CD=' + scwin.objParam.MKTACT_TP_CD;
            param += '&{P}V_BND_APPL_ID=' + scwin.objParam.BND_APPL_ID;
            param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.objParam.BND_LIST_PROCS_TP_CD;
        } else if (scwin.objParam.MKTACT_TP_CD === undefined || scwin.objParam.MKTACT_TP_CD === '') {
            qryId = 'lds.stf.bnschg.select.selectChgBndListFeeOrAnulFee';
            param += '&{P}V_GRP_PROCS_DD=' + scwin.objParam.GRP_PROCS_DD;
            param += '&{P}V_GRP_PROCS_TM=' + scwin.objParam.GRP_PROCS_TM;
        }
        $c.bns.fn_SearchBns('ULDBNS20002.xml', dts_DtlInfo, dsNm, qryId, param);

        // 상장수수료 및 연부과금에서 호출하는 경우 접수번호 숨김
        if (scwin.objParam.MKTACT_TP_CD === undefined || scwin.objParam.MKTACT_TP_CD === '') {
            lbl_BndApplId.hide();
            txb_BndApplId.hide();
        }
        label_44.hide();
        chk_ExchMbr.hide();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20002.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_DtlInfo_OnLoadError
 * @description dts_DtlInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20002.dts_DtlInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DtlInfo_OnLoadCompleted
 * @description dts_DtlInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadCompleted = async function(rowcount) {
    try {
        // 담당자명이 비어 있는 경우, 사용자 이름을 보여줌
        if (txb_ChrgNm.getValue() === '') {
            txb_ChrgNm.setValue(js_emp_nm);
        }
        // DR 및 Exa DB체크
        if (js_svrGubun === 'dr') {
            await $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
            // return false;

        } else {
            $c.bns.fn_BnsCheckExaDb('ULDBNS20002.xml', dts_CheckExa, '1');
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20002.dts_DtlInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_FeeDepoDd_onclick
 * @description img_FeeDepoDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FeeDepoDd_onclick = function() {
    try {
        if (dts_DtlInfo.getRowCount() === 0) return;
        popUpCalendar2(edt_FeeDepoDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20002.img_FeeDepoDd_onclick" });
    }
};

/**
 * @method
 * @name cmb_ChgListFeeFuPayYn_onselchange
 * @description cmb_ChgListFeeFuPayYn onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ChgListFeeFuPayYn_onselchange = function() {
    try {
        if (cmb_ChgListFeeFuPayYn.getValue() === "E") {
            // 상장수수료 면제사유 활성화
            cmb_BndListFeeExmptRsnCd.setDisabled(true);
        } else {
            // 상장수수료 면제사유 비활성화 및 초기화
            cmb_BndListFeeExmptRsnCd.setDisabled(true);
            cmb_BndListFeeExmptRsnCd.setValue('');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20002.cmb_ChgListFeeFuPayYn_onselchange" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        if (dts_DtlInfo.getRowCount() === 0) return;
        // 필수 입력 값 체크
        if (await scwin.inputCheck() === false) return;

        /** 201, 205, 202 */
        if (scwin.objParam.MKTACT_TP_CD === '201' || scwin.objParam.MKTACT_TP_CD === '205' || scwin.objParam.MKTACT_TP_CD === '202') {
            let prt = $c.frame.path("../");
            prt.dts_ChgListFee.ImportData(dts_DtlInfo.getRangeJSON(1, dts_DtlInfo.getRowCount(), false));
            let arrPar = new Array();
            arrPar[0] = {
                REG_YN: "Y"
            };
            scwin.fn_SetPar(arrPar);
            await $c.win.closePopup();
        } else if (scwin.objParam.MKTACT_TP_CD === undefined || scwin.objParam.MKTACT_TP_CD === '') {
            scwin.update();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20002.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20002.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20002.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        dts_DtlInfo.Reset();
        let arrPar = new Array();
        arrPar[0] = {
            REG_YN: "Y"
        };
        scwin.fn_SetPar(arrPar);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20002.trs_Save_OnSuccess" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    let prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        let arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.objParam.BND_APPL_ID = arrPar[0].BND_APPL_ID;
        scwin.objParam.BND_LIST_PROCS_TP_CD = arrPar[0].BND_LIST_PROCS_TP_CD;
        if (arrPar.MKTACT_TP_CD !== undefined || arrPar[0].MKTACT_TP_CD !== '') {
            scwin.objParam.MKTACT_TP_CD = arrPar[0].MKTACT_TP_CD;
        } else {
            scwin.objParam.GRP_PROCS_DD = arrPar[0].GRP_PROCS_DD;
            scwin.objParam.GRP_PROCS_TM = arrPar[0].GRP_PROCS_TM;
        }
    }
};

/**
 * @method
 * @name setComboCode
 * @description 콤보데이터 정의 (채권상장수수료면제사유코드)
 * @returns {void}
 * @hidden N
 */
scwin.setComboCode = function() {
    // 변경상장수수료의 경우, '6 주권상장법인' 제외 안함 (신규/추가상장수수료 제외)
    $c.bns.fn_SetBnsCombo('ULDBNS20002.xml', dts_ListFeeExamptFsnCd, '03385');
};

/**
 * @method
 * @name inputCheck
 * @description 필수 입력 값을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputCheck = async function() {
    if (txb_IsurNm.getValue() === '') {
        await $c.win.alert("등록할 데이타가 없습니다.");
        return false;
    }
    if (txb_FeeGrpNm.getValue() === '') {
        await $c.win.alert("그룹명을 입력하십시오.");
        return false;
    }
    // 자리수 체크
    if (!$c.stf.checkMaxLength(txb_FeeGrpNm, txb_FeeGrpNm.maxLength, lbl_FeeGrpNm.outerText)) return false;
    if (!$c.stf.checkMaxLength(txb_ChrgNm, 80, '담당자')) return false;
    if (cmb_ChgListFeeFuPayYn.getValue() === '') {
        await $c.win.alert("[변경장수수료 납부여부]를 선택하십시오.");
        return false;
    }
    if (cmb_ChgListFeeFuPayYn.getValue() === "E" && cmb_BndListFeeExmptRsnCd.getValue() === '') {
        await $c.win.alert("상장수수료 면제시에는 면제사유를 선택하십시오.");
        return false;
    }

    // 면제가 아닐경우, 입금일 체크
    if (cmb_ChgListFeeFuPayYn.getValue() !== "E") {
        if (edt_FeeDepoDd.getValue() === '') {
            await $c.win.alert("상장수수료 면제가 아닌 경우, 입금일을 입력하십시오.");
            return false;
        }
        if (edt_FeeDepoDd.getValue() > scwin.vCurDate) {
            await $c.win.alert("입금일은 오늘 이후 날짜를 입력하실 수 없습니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name exchMbr
 * @description 거래소회원 체크 여부
 * @returns {void}
 * @hidden N
 */
scwin.exchMbr = function() {
    if (dts_DtlInfo.getCellData(1, "KSE_MEM_YN") === 'Y') {
        chk_ExchMbr.setValue(1);
    } else {
        chk_ExchMbr.setValue(0);
    }
};

/**
 * @method
 * @name update
 * @description 상장수수료 및 연부과금에서  저장 시, 수정처리
 * @returns {void}
 * @hidden N
 */
scwin.update = function() {
    // 변경된 데이터가 없더라도 데이터셋 전송
    dts_DtlInfo.UseChangeInfo = "False";
    let url = "/bns/ChgList.do?method=updateChgListFee";
    url += "&SCREN_ID=" + 'ULDBNS20002.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};
